def transform(g):
    h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    P=sorted((i,j) for i in range(h) for j in range(w) if g[i][j]==2)
    top=P[0]; mc=top[1]
    # same-row pairs: full horizontal connection
    pair_rows={}
    for i,(r,c) in enumerate(P):
        for (r2,c2) in P[i+1:]:
            if r2==r: pair_rows.setdefault(r,[]).append((c,c2))
    pair_row=set(pair_rows)
    for r,segs in pair_rows.items():
        lo=min(min(s) for s in segs); hi=max(max(s) for s in segs)
        for j in range(lo,hi+1): out[r][j]=3
    # main vertical line from topmost: stop before nearest 2 below
    below=[r for r,c in P if r>top[0]]
    stop_row=min(below) if below else top[0]+1
    for i in range(top[0]+1, stop_row): out[i][mc]=3
    done={(r,c) for r in pair_row for (a,b) in pair_rows[r] for c in range(a,b+1)}
    for (r,c) in P[1:]:
        if r in pair_row: continue
        # horizontal ray toward main column (inclusive), cells strictly between
        between=[j for j in (range(c+1,mc+1) if c<mc else range(mc,c))]
        if len(between)>=2:
            for j in between: out[r][j]=3
        else:
            # fallback: vertical toward nearest line row (pair row, or own column toward topmost)
            if c==mc:
                for i in range(r-1, top[0], -1): out[i][c]=3
            elif pair_row:
                pr=min(pair_row, key=lambda x:abs(x-r))
                if pr>r:
                    for i in range(r+1,pr): out[i][c]=3
                else:
                    for i in range(r-1,pr,-1): out[i][c]=3
    return out

